    gradient: "linear-gradient(135deg, #fbbf24, #8b5cf6)",
    category: "Connection",
    readTime: "1 min",
    slides: [
      { heading: "A good conversation is biology.", text: "Real social connection triggers the same brain chemistry as other things that feel good. It's not incidental — it's what you're wired for.", emoji: "🧬", animation: "zoom", bgImage: "/images/image9.png", character: "couple" },
      { heading: "The lift is real and it lasts.", text: "After a genuinely good chat, you feel lighter, clearer, more optimistic. That mood carries into the next few hours. Not a coincidence.", emoji: "🚀", animation: "slide-left", bgImage: "/images/image10.png", character: "girl" },
      { heading: "Your wellbeing needs connection.", text: "Not just wants it. Research is clear that the quality of your social connections is one of the biggest predictors of overall wellbeing.", emoji: "💊", animation: "slide-right", bgImage: "/images/image11.png", character: "boy" },
      { heading: "One chat can shift the whole day.", text: "You're not being dramatic. A single real conversation is capable of genuinely turning a bad day around. That's worth making time for.", emoji: "💛", animation: "bounce", bgImage: "/images/image12.png", character: "couple", cta: { label: "Shift your day", href: "/chat" } },
    ],
