    title: "How to Give a Compliment That Actually Lands",
    shortTitle: "Compliments That Land",
    emoji: "🎯",
    gradient: "linear-gradient(135deg, #fbbf24, #ec4899)",
    category: "Chat Tips",
    readTime: "1 min",
    slides: [
      { heading: "Most compliments slide right off.", text: "'You're so nice' lands nowhere because it could apply to anyone. A real compliment is specific to this person.", emoji: "🔍", animation: "zoom", bgImage: "/images/image13.png", character: "boy" },
      { heading: "Compliment the action, not just the trait.", text: "'The way you explained that was really clear' hits harder than 'you're smart' because it proves you were paying attention.", emoji: "💡", animation: "slide-left", bgImage: "/images/image14.png", character: "girl" },
      { heading: "Say it once and mean it.", text: "One real compliment beats five automatic ones. Deliver it, let it land, move on. Don't undermine it by over-explaining.", emoji: "🎯", animation: "slide-right", bgImage: "/images/image15.png", character: "couple" },
      { heading: "The best compliments make people feel seen.", text: "Not 'you're great' but 'I noticed this specific thing about you' — that's what people carry with them long after.", emoji: "✨", animation: "bounce", bgImage: "/images/image16.png", character: "boy", cta: { label: "Make someone feel seen", href: "/chat" } },
    ],
