    gradient: "linear-gradient(135deg, #3b82f6, #14b8a6)",
    category: "Connection",
    readTime: "1 min",
    slides: [
      { heading: "You're not a project that needs completing.", text: "The idea that you need to become a better version of yourself before you deserve connection is a lie your insecurities tell you.", emoji: "🪞", animation: "zoom", bgImage: "/images/image12.png", character: "girl" },
      { heading: "Your current self is already enough.", text: "Imperfect, figuring things out, sometimes anxious — exactly as you are right now, you have things worth offering in a conversation.", emoji: "💎", animation: "slide-left", bgImage: "/images/image13.png", character: "boy" },
      { heading: "Vulnerability is connection, not weakness.", text: "The parts of you still in process are what make you relatable and human. Perfect people are impossible to connect with.", emoji: "🤝", animation: "slide-right", bgImage: "/images/image14.png", character: "couple" },
      { heading: "Show up now.", text: "Not when you're more confident, thinner, further along. Now. The connection you need is available to you as you are today.", emoji: "💛", animation: "bounce", bgImage: "/images/image15.png", character: "girl", cta: { label: "Connect as you are", href: "/chat" } },
    ],
