    title: "How to Start Over After a Bad Chat",
    shortTitle: "Start Over",
    emoji: "🔄",
    gradient: "linear-gradient(135deg, #6366f1, #ec4899)",
    category: "Chat Tips",
    readTime: "1 min",
    slides: [
      { heading: "One bad chat isn't a verdict.", text: "A conversation that went nowhere — or sideways — says nothing about your worth or your ability. It was just one chat among thousands possible.", emoji: "🎭", animation: "zoom", bgImage: "/images/image6.png", character: "girl" },
      { heading: "Don't carry it into the next one.", text: "The biggest mistake is letting a bad chat make you guarded for the next person. They didn't cause it. Start fresh.", emoji: "🧹", animation: "slide-left", bgImage: "/images/image7.png", character: "boy" },
      { heading: "Reset your energy first.", text: "Take a breath. Close the app for a minute. Come back when you're not carrying frustration from the last conversation.", emoji: "🌬️", animation: "slide-right", bgImage: "/images/image8.png", character: "couple" },
      { heading: "The next stranger is a clean slate.", text: "They know nothing about what just happened. To them, you're a fresh start. Give yourself the same gift.", emoji: "✨", animation: "bounce", bgImage: "/images/image9.png", character: "girl", cta: { label: "Start fresh now", href: "/chat" } },
    ],
