    category: "Chat Tips",
    readTime: "1 min",
    slides: [
      { heading: "People remember what matters to them.", text: "So when you remember a small detail someone shared, it sends a clear message: you matter to me.", emoji: "💡", animation: "zoom", bgImage: "/images/image14.png", character: "girl" },
      { heading: "It's the smallest things that land.", text: "Their dog's name. The exam they were nervous about. The trip they were excited for. Bring it back up and watch their face light up.", emoji: "🎯", animation: "slide-left", bgImage: "/images/image15.png", character: "boy" },
      { heading: "In text, you have an advantage.", text: "You can scroll back. Skim the last conversation before the next one. A little effort makes you look like you have a perfect memory.", emoji: "📜", animation: "slide-right", bgImage: "/images/image16.png", character: "couple" },
      { heading: "Memory is a form of love.", text: "To remember someone's details is to say: you're not forgettable to me. Few gifts are simpler or more powerful.", emoji: "❤️", animation: "bounce", bgImage: "/images/image17.png", character: "girl", cta: { label: "Make someone feel remembered", href: "/chat" } },
    ],
