    shortTitle: "Asking for Advice",
    emoji: "🙏",
    gradient: "linear-gradient(135deg, #14b8a6, #6366f1)",
    category: "Connection",
    readTime: "1 min",
    slides: [
      { heading: "Asking for advice is a gift.", text: "It tells the other person: I value your perspective. I trust your judgment. Few things make someone feel more respected.", emoji: "🎁", animation: "zoom", bgImage: "/images/image9.png", character: "girl" },
      { heading: "It flips the dynamic.", text: "Instead of trying to impress them, you're inviting them to help you. Vulnerability like this builds trust faster than confidence ever could.", emoji: "🔄", animation: "slide-left", bgImage: "/images/image10.png", character: "boy" },
      { heading: "People love feeling useful.", text: "When someone helps you, they become invested in you. The act of giving advice deepens their connection to your story.", emoji: "🌱", animation: "slide-right", bgImage: "/images/image11.png", character: "couple" },
      { heading: "Just make it genuine.", text: "Ask about something you actually care about. People can tell the difference between real curiosity and flattery.", emoji: "💬", animation: "bounce", bgImage: "/images/image12.png", character: "girl", cta: { label: "Start a real exchange", href: "/chat" } },
    ],
