    gradient: "linear-gradient(135deg, #f97316, #ec4899)",
    category: "Chat Tips",
    readTime: "1 min",
    slides: [
      { heading: "Everyone has stories. Few tell them well.", text: "The difference between a forgettable chat and a captivating one is often just how you tell what happened to you.", emoji: "🎬", animation: "zoom", bgImage: "/images/image8.png", character: "boy" },
      { heading: "Start in the middle of the action.", text: "Skip the long setup. Drop them into the moment. 'So I'm standing there, completely soaked...' beats 'so earlier today I decided to...'", emoji: "⚡", animation: "slide-left", bgImage: "/images/image9.png", character: "girl" },
      { heading: "Specific details make it real.", text: "Not 'it was funny' but the exact absurd thing that happened. Specifics let the other person see it, not just hear about it.", emoji: "🎯", animation: "slide-right", bgImage: "/images/image10.png", character: "couple" },
      { heading: "End with a feeling, not just facts.", text: "What did the moment mean? How did it leave you? The best stories land emotionally, not just informationally.", emoji: "💛", animation: "bounce", bgImage: "/images/image11.png", character: "boy", cta: { label: "Tell your story", href: "/chat" } },
    ],
