    gradient: "linear-gradient(135deg, #a78bfa, #f472b6)",
    category: "Chat Tips",
    readTime: "1 min",
    slides: [
      { heading: "Quiet doesn't mean closed.", text: "A quiet person often has the richest inner world. They're just waiting to feel safe enough to share it.", emoji: "🌊", animation: "zoom", bgImage: "/images/image16.png", character: "girl" },
      { heading: "Share first.", text: "Going first with something a little personal shows them the water's warm. Vulnerability invites vulnerability.", emoji: "🙋", animation: "slide-left", bgImage: "/images/image17.png", character: "boy" },
      { heading: "Ask specific, easy questions.", text: "Broad questions overwhelm. 'What's been the best part of your week?' is easier to answer than 'tell me about yourself.'", emoji: "❓", animation: "slide-right", bgImage: "/images/image18.png", character: "couple" },
      { heading: "Reward every opening.", text: "When they share something small, respond with warmth. They're testing whether it's safe to share more. Show them it is.", emoji: "💛", animation: "bounce", bgImage: "/images/image6.png", character: "girl", cta: { label: "Draw someone out", href: "/chat" } },
    ],
